<template><div class="toast-stack" aria-live="polite"><TransitionGroup name="toast"><div v-for="item in items" :key="item.id" class="toast" :class="item.kind"><Icon :name="item.kind === 'error' ? 'exclamationTriangle' : 'check'" size="sm" /><span>{{ item.message }}</span><button type="button" class="icon-button" aria-label="Dismiss" @click="remove(item.id)"><Icon name="x" size="sm" /></button></div></TransitionGroup></div></template>
<script setup lang="ts">import { storeToRefs } from 'pinia'; import Icon from '../icons/Icon.vue'; import { useToastStore } from '../../stores/toast'; const store=useToastStore(); const {items}=storeToRefs(store); const remove=(id:number)=>store.remove(id)</script>
